pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 fundAmount, uint256 withdrawAmount) public {
        vm.assume(caller != address(0));
        vm.assume(fundAmount > 0);
        // Withdraw amount is bounded by the contract's balance after funding;
        // the bug only triggers when someone other than Owner calls withdraw and the contract has a positive balance.
        vm.assume(withdrawAmount > 0);

        // Fund the contract with some Ether via a call to Command or multiplicate to ensure a positive balance.
        vm.deal(caller, fundAmount);
        vm.prank(caller);
        // Multiplicate: if msg.value >= address(this).balance it transfers entire balance+msg.value to adr;
        // this is a convenient way to put Ether into the contract without being Owner. Send to address(0) to keep it in the contract? No, it sends to adr.
        // Better: use Command with empty data to send Ether directly to the contract itself as a payable call.
        c.Command{value: fundAmount}(address(c), "");

        // Now the contract has balance = fundAmount.
        // Try to withdraw the balance as the non-Owner caller.
        // If caller is the Owner, the reference will succeed; for correctness we must ensure the caller is NOT the Owner in the test,
        // because the property is "only Owner can withdraw". So we exclude the Owner.
        address owner = c.Owner();
        vm.assume(caller != owner);

        // Record balance before withdraw.
        uint256 balBefore = address(c).balance;

        // Attempt withdraw as non-Owner.
        bool ok;
        vm.prank(caller);
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balAfter = address(c).balance;

        // Reference C: only Owner can withdraw; non-Owner call reverts (ok == false), balance remains unchanged.
        // Buggy C: non-Owner can withdraw, so the call succeeds (ok == true) and balance becomes 0.
        // Assert that if the withdraw succeeded (ok == true), the caller MUST be the Owner.
        // Equivalent: if caller != Owner, then ok must be false.
        assertTrue(ok ? (caller == owner) : (caller != owner));
    }
}

